/**
 * What the app reports while browsing.
 */
public interface BrowseSinkInterface {
    
    /**
     * Browsing failed (for example, local network access was denied).
     */
    fun `failed`(`reason`: kotlin.String)
    
    /**
     * A device went away.
     */
    fun `lost`(`instance`: kotlin.String)
    
    /**
     * A device was resolved: its raw TXT entries, its addresses as text
     * and its port.
     */
    fun `resolved`(`instance`: kotlin.String, `txt`: List<TxtEntry>, `addresses`: List<kotlin.String>, `port`: kotlin.UShort)
    
    companion object
}

