/**
 * @suppress
 */
public object FfiConverterTypePlatformDiscovery: FfiConverter<PlatformDiscovery, Long> {
    internal val handleMap = UniffiHandleMap<PlatformDiscovery>()

    override fun lower(value: PlatformDiscovery): Long {
        if (value is PlatformDiscoveryImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): PlatformDiscovery {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return PlatformDiscoveryImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): PlatformDiscovery {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: PlatformDiscovery) = 8UL

    override fun write(value: PlatformDiscovery, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



