    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: FileStatus) = 4UL

    override fun write(value: FileStatus, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * Something the app should show. Incoming transfers are identified by
 * `transfer_id` (unique among running transfers); outgoing ones by their
 * operation id.
 */
sealed class NodeEvent {
    
    /**
     * The receiver is listening.
     */
    data class ReceiverStarted(
        /**
         * Its state.
         */
        val `info`: io.github.dropumi.ffi.ReceiverInfo) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * The receiver stopped.
     */
    data class ReceiverStopped(
        /**
         * Why.
         */
        val `reason`: io.github.dropumi.ffi.ReceiverStopReason) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * The receive policy changed (including an Everyone window ending).
     */
    data class PolicyChanged(
        /**
         * New policy.
         */
        val `policy`: io.github.dropumi.ffi.ReceivePolicy, 
        /**
         * New accept mode.
         */
        val `accept`: io.github.dropumi.ffi.AcceptMode, 
        /**
         * When an Everyone window ends (Unix seconds).
         */
        val `everyoneUntil`: kotlin.ULong?) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * Advertising could not start; manual addresses still work.
     */
    data class DiscoveryUnavailable(
        /**
         * Why (local display only).
         */
        val `reason`: kotlin.String) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A device appeared or changed.
     */
    data class PeerFound(
        /**
         * The device.
         */
        val `peer`: io.github.dropumi.ffi.NearbyPeer) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A device went away.
     */
    data class PeerLost(
        /**
         * Its instance.
         */
        val `instance`: kotlin.String) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A secure channel is up.
     */
    data class Connected(
        /**
         * The operation, for outgoing work.
         */
        val `operation`: kotlin.ULong?, 
        /**
         * The peer.
         */
        val `peer`: io.github.dropumi.ffi.PeerInfo) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * The session code (shown in every session).
     */
    data class SessionCode(
        /**
         * The operation, for outgoing work.
         */
        val `operation`: kotlin.ULong?, 
        /**
         * The peer.
         */
        val `peer`: io.github.dropumi.ffi.PeerInfo, 
        /**
         * Six digits.
         */
        val `code`: kotlin.String) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * An offer was sent.
     */
    data class OfferSent(
        /**
         * The operation.
         */
        val `operation`: kotlin.ULong, 
        /**
         * Transfer id.
         */
        val `transferId`: kotlin.String, 
        /**
         * The receiver.
         */
        val `peer`: io.github.dropumi.ffi.PeerInfo, 
        /**
         * Number of files.
         */
        val `files`: kotlin.UInt, 
        /**
         * Total size.
         */
        val `totalBytes`: kotlin.ULong) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * An offer arrived (a `PromptOpened` follows when the user must answer).
     */
    data class OfferReceived(
        /**
         * Transfer id.
         */
        val `transferId`: kotlin.String, 
        /**
         * The sender.
         */
        val `peer`: io.github.dropumi.ffi.PeerInfo, 
        /**
         * Number of files.
         */
        val `files`: kotlin.UInt, 
        /**
         * Total size.
         */
        val `totalBytes`: kotlin.ULong) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * The user must answer.
     */
    data class PromptOpened(
        /**
         * The question.
         */
        val `prompt`: io.github.dropumi.ffi.Prompt) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A prompt went away; later answers are refused.
     */
    data class PromptClosed(
        /**
         * Prompt id.
         */
        val `id`: kotlin.ULong, 
        /**
         * Why.
         */
        val `reason`: io.github.dropumi.ffi.PromptCloseReason) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * The receiver accepted.
     */
    data class TransferAccepted(
        /**
         * The operation, for outgoing work.
         */
        val `operation`: kotlin.ULong?, 
        /**
         * Transfer id.
         */
        val `transferId`: kotlin.String) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * Progress (at most ten per second per transfer).
     */
    data class TransferProgress(
        /**
         * The operation, for outgoing work.
         */
        val `operation`: kotlin.ULong?, 
        /**
         * Transfer id.
         */
        val `transferId`: kotlin.String, 
        /**
         * Progress.
         */
        val `progress`: io.github.dropumi.ffi.Progress) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * The receiver reported a file's result to this sender.
     */
    data class FileSent(
        /**
         * The operation.
         */
        val `operation`: kotlin.ULong, 
        /**
         * Transfer id.
         */
        val `transferId`: kotlin.String, 
        /**
         * File index.
         */
        val `index`: kotlin.UInt, 
        /**
         * Result.
         */
        val `status`: io.github.dropumi.ffi.FileStatus) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A received file is stored and checked.
     */
    data class FileSaved(
        /**
         * Transfer id.
         */
        val `transferId`: kotlin.String, 
        /**
         * File index.
         */
        val `index`: kotlin.UInt, 
        /**
         * Final file name in the receive directory (never a path).
         */
        val `savedAs`: kotlin.String, 
        /**
         * Size.
         */
        val `size`: kotlin.ULong, 
        /**
         * BLAKE3 digest (hex).
         */
        val `blake3`: kotlin.String) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A received file was not stored.
     */
    data class FileFailed(
        /**
         * Transfer id.
         */
        val `transferId`: kotlin.String, 
        /**
         * File index.
         */
        val `index`: kotlin.UInt, 
        /**
         * Result.
         */
        val `status`: io.github.dropumi.ffi.FileStatus) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A transfer ended.
     */
    data class TransferFinished(
        /**
         * The operation, for outgoing work.
         */
        val `operation`: kotlin.ULong?, 
        /**
         * Direction.
         */
        val `direction`: io.github.dropumi.ffi.Direction, 
        /**
         * The result.
         */
        val `result`: io.github.dropumi.ffi.TransferResult) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A pairing window is open on this port.
     */
    data class PairingWindowOpened(
        /**
         * The operation.
         */
        val `operation`: kotlin.ULong, 
        /**
         * Port.
         */
        val `port`: kotlin.UShort) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * Pairing ended.
     */
    data class PairingFinished(
        /**
         * The operation.
         */
        val `operation`: kotlin.ULong, 
        /**
         * The result.
         */
        val `result`: io.github.dropumi.ffi.PairingResult) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A session ended without a transfer (denied, failed handshake, …).
     */
    data class SessionClosed(
        /**
         * The peer, if it was authenticated.
         */
        val `peer`: io.github.dropumi.ffi.PeerInfo?, 
        /**
         * Error code or "normal".
         */
        val `code`: kotlin.String) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * A problem that did not stop anything (local display only).
     */
    data class Warning(
        /**
         * Message.
         */
        val `message`: kotlin.String) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * Less important events were dropped because the app fell behind.
     */
    data class EventsDropped(
        /**
         * How many.
         */
        val `count`: kotlin.ULong) : NodeEvent()
        
    {
        

        companion object
    }
    
    /**
     * The app fell far behind: reload everything with `snapshot()`.
     */
    object ResyncRequired : NodeEvent()
    
    

    

    
    


    companion object
}

